pub fn remove(&mut self, index: usize) -> A::Item {
  let targets: &mut [A::Item] = &mut self.deref_mut()[index..];
  let mut spare = A::Item::default();
  for target in targets.iter_mut().rev() {
    spare = replace(target, spare);
  }
  self.len -= 1;
  spare
}
